@section('content')<div class="mx-auto max-w-[100rem]"><a href="{{ route('projects.show',$project) }}" class="text-sm font-semibold text-indigo-700">← {{ $project->name }}</a><form class="mt-4 flex gap-2"><label class="sr-only" for="board-search">Search board</label><input id="board-search" name="q" value="{{ $query }}" placeholder="Search board" class="rounded-xl border border-slate-300 px-4 py-2 focus:outline-none focus:ring-4 focus:ring-indigo-500/15"><x-button variant="secondary">Filter</x-button></form><div class="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-6" data-board>@foreach($statuses as $status)<section class="min-w-0 rounded-2xl bg-slate-100 p-3" data-column="{{ $status->value }}"><h2 class="px-2 text-sm font-bold text-slate-700">{{ ucwords(str_replace('_',' ',$status->value)) }} <span class="text-slate-400">{{ $columns[$status->value]->count() }}</span></h2><div class="mt-3 min-h-16 space-y-3" data-cards>@foreach($columns[$status->value] as $task)<article draggable="true" data-task="{{ $task->id }}" data-version="{{ $task->version }}" class="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><a href="{{ route('tasks.show',$task) }}" class="font-semibold text-indigo-700">{{ $task->number }}</a><p class="mt-1 text-sm font-semibold">{{ $task->title }}</p><p class="mt-2 text-xs text-slate-500">{{ $task->assignee?->name ?: 'Unassigned' }}</p><form method="POST" action="{{ route('tasks.status',$task) }}" class="mt-3 flex gap-2">@csrf @method('PATCH')<input type="hidden" name="expected_version" value="{{ $task->version }}"><label class="sr-only" for="status-{{ $task->id }}">Move {{ $task->number }}</label><select id="status-{{ $task->id }}" name="status" class="min-w-0 flex-1 rounded border border-slate-300 text-xs">@foreach($statuses as $option)<option value="{{ $option->value }}" @selected($option===$status)>{{ $option->value }}</option>@endforeach</select><button class="text-xs font-semibold text-indigo-700">Move</button></form></article>@endforeach</div></section>@endforeach</div></div><script>document.querySelectorAll('[draggable]').forEach(c=>{c.addEventListener('dragstart',e=>e.dataTransfer.setData('task',c.dataset.task));});document.querySelectorAll('[data-cards]').forEach(zone=>{zone.addEventListener('dragover',e=>e.preventDefault());zone.addEventListener('drop',async e=>{e.preventDefault();let id=e.dataTransfer.getData('task'),card=document.querySelector('[data-task="'+id+'"]'),column=zone.closest('[data-column]').dataset.column;if(!card)return;let version=card.dataset.version,csrf=document.querySelector('meta[name=csrf-token]').content;let response=await fetch('/tasks/'+id+'/status',{method:'PATCH',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify({status:column,expected_version:+version})});if(response.ok)location.reload();else alert('Move conflicted or is not permitted. Refresh and try again.');});});</script>@endsection
